public static class LogisticsErrors{public static Error Invalid=>Error.Validation("logistics.invalid_data");public static Error NotFound=>Error.NotFound("logistics.not_found");public static Error Concurrency=>Error.Concurrency("logistics.concurrency_conflict");public static Error InvalidTransition=>Error.BusinessRule("logistics.invalid_transition");public static Error NotReady=>Error.BusinessRule("logistics.not_ready");public static Error OverPackaged=>Error.BusinessRule("logistics.over_packaged");public static Error AlreadyAssigned=>Error.BusinessRule("logistics.package_already_assigned");public static Error ReasonRequired=>Error.Validation("logistics.reason_required");}
public static class LogisticsText{public static string? Code(string?x,int max=80){if(string.IsNullOrWhiteSpace(x))return null;string s=x.Trim().ToUpperInvariant();return s.Length<=max&&s.All(c=>char.IsAsciiLetterOrDigit(c)||c is '_' or '-' or '.')?s:null;}public static string? Text(string?x,int max,bool optional=false){if(string.IsNullOrWhiteSpace(x))return optional?null:null;string s=x.Trim();return s.Length<=max?s:null;}}
public sealed class Package{private Package(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid OrderId{get;private set;}public string PackageNumber{get;private set;}="";public string PackageTypeCode{get;private set;}="";public decimal WeightKg{get;private set;}public decimal LengthCm{get;private set;}public decimal WidthCm{get;private set;}public decimal HeightCm{get;private set;}public PackageStatus Status{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset?CompletedAtUtc{get;private set;}public Guid?CompletedByUserId{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public static Result<Package>Create(Guid company,Guid order,string number,string type,decimal weight,decimal length,decimal width,decimal height,DateTimeOffset now){string?n=LogisticsText.Code(number,40),t=LogisticsText.Code(type,50);if(company==Guid.Empty||order==Guid.Empty||n is null||t is null||weight<=0||length<=0||width<=0||height<=0)return Result.Failure<Package>(LogisticsErrors.Invalid);return Result.Success(new Package{Id=Guid.NewGuid(),CompanyId=company,OrderId=order,PackageNumber=n,PackageTypeCode=t,WeightKg=weight,LengthCm=length,WidthCm=width,HeightCm=height,Status=PackageStatus.Draft,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1});}public Result Complete(Guid actor,long expected,DateTimeOffset now){if(Status==PackageStatus.Completed)return Result.Success();if(expected!=Version)return Result.Failure(LogisticsErrors.Concurrency);if(Status!=PackageStatus.Draft)return Result.Failure(LogisticsErrors.InvalidTransition);Status=PackageStatus.Completed;CompletedAtUtc=now;CompletedByUserId=actor;Touch(now);return Result.Success();}public Result Handoff(long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(LogisticsErrors.Concurrency);if(Status!=PackageStatus.Completed)return Result.Failure(LogisticsErrors.InvalidTransition);Status=PackageStatus.AtShippingWarehouse;Touch(now);return Result.Success();}public Result Release(long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(LogisticsErrors.Concurrency);if(Status is not(PackageStatus.Completed or PackageStatus.AtShippingWarehouse))return Result.Failure(LogisticsErrors.InvalidTransition);Status=PackageStatus.ReleasedToShipment;Touch(now);return Result.Success();}private void Touch(DateTimeOffset n){UpdatedAtUtc=n;Version++;}}
public sealed class PackageItem{private PackageItem(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid PackageId{get;private set;}public Guid OrderId{get;private set;}public Guid OrderItemId{get;private set;}public decimal Quantity{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public static Result<PackageItem>Create(Guid company,Guid package,Guid order,Guid item,decimal quantity,DateTimeOffset now)=>quantity<=0||company==Guid.Empty||package==Guid.Empty||item==Guid.Empty?Result.Failure<PackageItem>(LogisticsErrors.Invalid):Result.Success(new PackageItem{Id=Guid.NewGuid(),CompanyId=company,PackageId=package,OrderId=order,OrderItemId=item,Quantity=quantity,CreatedAtUtc=now});}
public sealed class ShippingHandoff{private ShippingHandoff(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid PackageId{get;private set;}public Guid WarehouseId{get;private set;}public ShippingHandoffStatus Status{get;private set;}public DateTimeOffset ReceivedAtUtc{get;private set;}public Guid ReceivedByUserId{get;private set;}public DateTimeOffset?ReleasedAtUtc{get;private set;}public Guid?ReleasedByUserId{get;private set;}public long Version{get;private set;}public static ShippingHandoff Create(Guid company,Guid package,Guid warehouse,Guid actor,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,PackageId=package,WarehouseId=warehouse,Status=ShippingHandoffStatus.Received,ReceivedAtUtc=now,ReceivedByUserId=actor,Version=1};public Result Release(Guid actor,long expected,DateTimeOffset now){if(Status==ShippingHandoffStatus.Released)return Result.Success();if(expected!=Version)return Result.Failure(LogisticsErrors.Concurrency);Status=ShippingHandoffStatus.Released;ReleasedAtUtc=now;ReleasedByUserId=actor;Version++;return Result.Success();}}
public sealed class Shipment{private Shipment(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid OrderId{get;private set;}public string ShipmentNumber{get;private set;}="";public string CarrierCode{get;private set;}="";public string ShippingMethodCode{get;private set;}="";public string?TrackingCode{get;private set;}public DateTimeOffset?ShipmentDateUtc{get;private set;}public DateOnly?ExpectedDeliveryDate{get;private set;}public DateTimeOffset?DeliveredAtUtc{get;private set;}public DateTimeOffset?FailedAtUtc{get;private set;}public DateTimeOffset?ReturnedAtUtc{get;private set;}public Guid?ReturnWarehouseId{get;private set;}public ShipmentStatus Status{get;private set;}public string?LastReasonCode{get;private set;}public string?LastReasonText{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public static Result<Shipment>Create(Guid company,Guid order,string number,string carrier,string method,DateOnly?expected,DateTimeOffset now){string?n=LogisticsText.Code(number,40),c=LogisticsText.Code(carrier,50),m=LogisticsText.Code(method,50);if(n is null||c is null||m is null)return Result.Failure<Shipment>(LogisticsErrors.Invalid);return Result.Success(new Shipment{Id=Guid.NewGuid(),CompanyId=company,OrderId=order,ShipmentNumber=n,CarrierCode=c,ShippingMethodCode=m,ExpectedDeliveryDate=expected,Status=ShipmentStatus.Ready,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1});}public Result RegisterTracking(string tracking,long expected,DateTimeOffset now){string?t=LogisticsText.Code(tracking,100);if(t is null)return Result.Failure(LogisticsErrors.Invalid);if(TrackingCode==t)return Result.Success();if(expected!=Version)return Result.Failure(LogisticsErrors.Concurrency);if(Status is ShipmentStatus.Delivered or ShipmentStatus.Returned)return Result.Failure(LogisticsErrors.InvalidTransition);TrackingCode=t;Touch(now);return Result.Success();}public Result Ship(long expected,DateTimeOffset now)=>Transition(ShipmentStatus.Shipped,null,null,expected,now);public Result InTransit(long expected,DateTimeOffset now)=>Transition(ShipmentStatus.InTransit,null,null,expected,now);public Result Deliver(long expected,DateTimeOffset now)=>Transition(ShipmentStatus.Delivered,null,null,expected,now);public Result Fail(string code,string reason,long expected,DateTimeOffset now)=>Transition(ShipmentStatus.FailedDelivery,code,reason,expected,now);public Result Return(Guid warehouse,string code,string reason,long expected,DateTimeOffset now){if(Status==ShipmentStatus.Returned)return ReturnWarehouseId==warehouse?Result.Success():Result.Failure(LogisticsErrors.InvalidTransition);if(warehouse==Guid.Empty)return Result.Failure(LogisticsErrors.Invalid);Result r=Transition(ShipmentStatus.Returned,code,reason,expected,now);if(r.IsSuccess)ReturnWarehouseId=warehouse;return r;}private Result Transition(ShipmentStatus target,string?code,string?reason,long expected,DateTimeOffset now){if(Status==target)return Result.Success();if(expected!=Version)return Result.Failure(LogisticsErrors.Concurrency);bool allowed=(Status,target)is(ShipmentStatus.Ready,ShipmentStatus.Shipped)or(ShipmentStatus.Shipped,ShipmentStatus.InTransit)or(ShipmentStatus.InTransit,ShipmentStatus.Delivered)or(ShipmentStatus.Shipped,ShipmentStatus.FailedDelivery)or(ShipmentStatus.InTransit,ShipmentStatus.FailedDelivery)or(ShipmentStatus.FailedDelivery,ShipmentStatus.Returned);if(!allowed)return Result.Failure(LogisticsErrors.InvalidTransition);string?c=code is null?null:LogisticsText.Code(code,50),r=LogisticsText.Text(reason,500,true);if(target is ShipmentStatus.FailedDelivery or ShipmentStatus.Returned&&(c is null||r is null))return Result.Failure(LogisticsErrors.ReasonRequired);Status=target;LastReasonCode=c;LastReasonText=r;if(target==ShipmentStatus.Shipped)ShipmentDateUtc=now;if(target==ShipmentStatus.Delivered)DeliveredAtUtc=now;if(target==ShipmentStatus.FailedDelivery)FailedAtUtc=now;if(target==ShipmentStatus.Returned)ReturnedAtUtc=now;Touch(now);return Result.Success();}private void Touch(DateTimeOffset now){UpdatedAtUtc=now;Version++;}}
public sealed class ShipmentPackage{private ShipmentPackage(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid ShipmentId{get;private set;}public Guid PackageId{get;private set;}public DateTimeOffset AssignedAtUtc{get;private set;}public static ShipmentPackage Create(Guid company,Guid shipment,Guid package,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,ShipmentId=shipment,PackageId=package,AssignedAtUtc=now};}
